DECLARE @watermark_to VARCHAR(50) = NULL;

IF UPPER(@load_type) <> 'FULL'
   AND @watermark_column IS NOT NULL
   AND @target_schema IS NOT NULL
   AND @target_table IS NOT NULL
BEGIN
    DECLARE @sql NVARCHAR(MAX) = N'
        SELECT @res = CAST(MAX(' + QUOTENAME(@watermark_column) + N') AS NVARCHAR(50))
        FROM ' + QUOTENAME(@target_schema) + N'.' + QUOTENAME(@target_table);

    EXEC sp_executesql @sql, N'@res VARCHAR(50) OUTPUT', @res = @watermark_to OUTPUT;
END;

SELECT @watermark_to AS watermark_to;

IF @error_id IS NULL OR LTRIM(RTRIM(@error_id)) = ''
    THROW 51000, 'error_id is required.', 1;

IF @error_status NOT IN ('Resolved', 'Need Manual Check')
    THROW 51001, 'error_status must be Resolved or Need Manual Check.', 1;

UPDATE meta.error_logging_table
SET
    status = @error_status,
    updated_at = SYSUTCDATETIME()
WHERE error_id = @error_id
  AND status IN ('New', 'In-Progress');

